  "meta.ir_para_o_conteudo": "Ir al contenido",
  "projetos.apostilas_e_capas_salvas_no": "Cuadernillos y portadas guardados en el servidor. Abre un proyecto para continuar donde lo dejaste.",
  "projetos.importar_arquivo_json": "Importar archivo JSON",
  "prompt.apostila.atencao": "ATENCIÓN: sigue rigurosamente todas las especificaciones de abajo. NO mezcles el tipo de material ni el estilo visual con otros que no se hayan solicitado, NO cambies el formato pedido y NO supongas información que no se haya proporcionado.",
  "prompt.apostila.bncc_apenas": "Usa solo los códigos de la BNCC proporcionados. No agregues códigos por inferencia.",
  "prompt.apostila.bncc_sugerir": "Sugiere habilidades de la BNCC solo cuando exista una correspondencia verificable con la etapa y el componente curricular. Indica el código y la descripción fiel; si no puedes verificarlo, declara la limitación y no inventes.",
  "prompt.apostila.extensao.outros": "{n} páginas como máximo",
  "prompt.apostila.extensao.um": "{n} página como máximo",
  "prompt.apostila.final": "PRODUCE AHORA EL MATERIAL SOLICITADO.",
  "prompt.apostila.h_tarefa": "TAREA",
  "prompt.apostila.orientacoes": "Indicaciones adicionales: {valor}.",
  "prompt.apostila.papel": "ACTÚA COMO ESPECIALISTA EN EDUCACIÓN, DISEÑO INSTRUCCIONAL, DIRECCIÓN DE ARTE EDITORIAL Y PRODUCCIÓN DE MATERIAL DIDÁCTICO.",
  "prompt.apostila.s1_adapte": "Adapta el lenguaje, los ejemplos, el vocabulario y la progresión al público.",
  "prompt.apostila.s1_densidade": "Densidad del texto: {valor}.",
  "prompt.apostila.s1_escrita": "Estilo de escritura: {valor}.",
  "prompt.apostila.s1_extensao": "Extensión objetivo: {valor}.",
  "prompt.apostila.s1_hipoteses": "Declara tus supuestos cuando falten datos indispensables.",
  "prompt.apostila.s1_objetivo": "Objetivo de aprendizaje: {valor}.",
  "prompt.apostila.s1_profundidade": "Profundidad del contenido: {valor}.",
  "prompt.apostila.s1_publico": "Público objetivo: {valor}.",
  "prompt.apostila.s1_titulo": "PERFIL PEDAGÓGICO",
  "prompt.apostila.s2_bncc": "Códigos BNCC informados: {valor}.",
  "prompt.apostila.s2_ilustrativos": "Diferencia explícitamente los datos ilustrativos de los datos medidos, documentados o comprobados.",
  "prompt.apostila.s2_referencia": "Material de referencia obligatorio:",
  "prompt.apostila.s2_titulo": "CONFIGURACIÓN CURRICULAR Y FUENTES",
  "prompt.apostila.s3_1": "Presenta el título, los objetivos específicos, los requisitos previos y una ruta de aprendizaje.",
  "prompt.apostila.s3_2": "Organiza secciones progresivas, con explicaciones completas, definiciones, ejemplos resueltos y aplicaciones contextualizadas cuando corresponda.",
  "prompt.apostila.s3_3": "Incluye síntesis parciales, preguntas de verificación e indicaciones claras de transición entre temas.",
  "prompt.apostila.s3_4": "Termina con una síntesis general, actividades de fijación con dificultad progresiva y solucionario comentado.",
  "prompt.apostila.s3_5": "Respeta la extensión objetivo definida en el punto 1 ({extensao}): dimensiona el número de secciones, la profundidad de cada una y la cantidad de recursos visuales para que el material completo no supere el límite superior de páginas de ese rango.",
  "prompt.apostila.s3_6": "Haz una revisión final de consistencia pedagógica, conceptual, ortográfica y visual.",
  "prompt.apostila.s3_titulo": "ARQUITECTURA DEL MATERIAL",
  "prompt.apostila.s4_estilo": "Estilo visual: {valor}.",
  "prompt.apostila.s4_formato": "Formato prioritario: {valor}.",
  "prompt.apostila.s4_frequencia": "Frecuencia: {valor}.",
  "prompt.apostila.s4_hierarquia": "Usa una jerarquía tipográfica clara, espaciado cómodo, alto contraste, leyendas y consistencia visual. Garantiza la legibilidad en pantalla y en impresión y no dependas solo del color para transmitir significado.",
  "prompt.apostila.s4_nenhum_recurso": "ningún recurso obligatorio",
  "prompt.apostila.s4_paleta": "Paleta: {valor}.",
  "prompt.apostila.s4_personagens": "No uses figuras infantiles ni personajes si el público no es infantil. Si hay personajes, deben ser del grupo de edad de {publico}, acordes con el público objetivo.",
  "prompt.apostila.s4_prof_visual": "Profundidad visual: {valor}.",
  "prompt.apostila.s4_recursos": "Recursos obligatorios seleccionados: {valor}.",
  "prompt.apostila.s4_titulo": "SISTEMA VISUAL",
  "prompt.apostila.s5_diagramas": "DIAGRAMAS: especifica nodos, flechas, relaciones, dirección de lectura y una versión textual equivalente. Cuando sea útil, proporciona código Mermaid válido y simple.",
  "prompt.apostila.s5_graficos": "GRÁFICOS: elige el tipo adecuado para la comparación. No fabriques datos. Si no hay datos reales, proporciona solo el modelo y los campos necesarios, y marca cualquier ejemplo como ILUSTRATIVO.",
  "prompt.apostila.s5_icones": "ÍCONOS: usa un conjunto consistente con rótulos, sin reemplazar información esencial solo con símbolos.",
  "prompt.apostila.s5_ilustracoes": "ILUSTRACIONES: escribe briefings objetivos con escena, elementos, composición, encuadre, estilo, paleta, diversidad y restricciones. No supongas que la imagen ya fue generada.",
  "prompt.apostila.s5_infograficos": "INFOGRAFÍAS: combina jerarquía, bloques informativos, íconos, números y recorrido de lectura. Usa solo información presente o verificable.",
  "prompt.apostila.s5_intro": "Para cada recurso visual, entrega: (a) objetivo pedagógico; (b) posición sugerida; (c) contenido exacto; (d) título y leyenda; (e) descripción de producción; (f) texto alternativo accesible.",
  "prompt.apostila.s5_linhas": "LÍNEAS DE TIEMPO: incluye solo fechas verificables y diferencia el orden didáctico de la cronología histórica.",
  "prompt.apostila.s5_mapas_mentais": "MAPAS MENTALES: crea estructuras ricas, con concepto central, de 4 a 7 ramas principales, subramas, palabras clave cortas, relaciones nombradas y una leyenda. Evita las listas lineales disfrazadas de mapa.",
  "prompt.apostila.s5_quadros": "CUADROS COMPARATIVOS: define criterios consistentes, encabezados claros y notas para las excepciones.",
  "prompt.apostila.s5_titulo": "ESPECIFICACIÓN DE LOS RECURSOS VISUALES",
  "prompt.apostila.s6_1": "Escribe el material completo, no solo un resumen.",
  "prompt.apostila.s6_2": "Marca cada visual con bloques [VISUAL: tipo], [OBJETIVO], [CONTENIDO], [INSTRUCCIÓN GRÁFICA], [LEYENDA] y [TEXTO ALTERNATIVO].",
  "prompt.apostila.s6_3": "Para los diagramas Mermaid, usa bloques de código separados. Para los gráficos, entrega una tabla de datos antes de la especificación del gráfico.",
  "prompt.apostila.s6_4": "No declares que las imágenes o los gráficos fueron renderizados si solo describiste su producción.",
  "prompt.apostila.s6_5": "Usa unidades del SI y la notación correcta cuando corresponda.",
  "prompt.apostila.s6_titulo": "SALIDA Y MARCAS TÉCNICAS",
  "prompt.apostila.s7_1": "Título en mayúsculas con el tema principal.",
  "prompt.apostila.s7_2": "Línea de apoyo: asignatura | tipo de material | público objetivo.",
  "prompt.apostila.s7_3": "De 2 a 3 frases cortas que expliquen lo que el lector va a entender al final.",
  "prompt.apostila.s7_4": "Una lista de 4 a 6 viñetas que resuman los puntos clave, cada una con una línea como máximo.",
